async function checkCustomSelects(report) {
  const select = async (doc, label, value) => {
    const trigger = doc.querySelector(`.custom-select-trigger[aria-label="${label}"]`);
    trigger.scrollIntoView({ block: "center", behavior: "instant" });
    await pause(60);
    trigger.click();
    await waitFor(() => doc.querySelector('.custom-select-menu'), label + " popup");
    const popup = doc.querySelector('.custom-select-menu');
    const option = [...popup.querySelectorAll('[role="option"]')].find((item) => item.dataset.value === value);
    if (!option || option.disabled) throw new Error("Unavailable option: " + label + " / " + value);
    const bounds = popup.getBoundingClientRect();
    const view = doc.defaultView;
    if (bounds.left < 0 || bounds.top < 0 || bounds.right > view.innerWidth || bounds.bottom > view.innerHeight || !popup.contains(doc.elementFromPoint(bounds.left + 10, bounds.top + 10)))
      throw new Error("Popup clipped or outside viewport: " + label);
    option.click();
    await waitFor(() => !doc.querySelector('.custom-select-menu'), label + " dismissed");
  };

  document.querySelector('[aria-label="Appearance and language"]').click();
  await waitFor(() => document.querySelector('.appearance-dialog[open]'), "appearance dialog");
  const dialog = document.querySelector('.appearance-dialog');
  await select(document, "Language", "ja");
  await waitFor(() => dialog.querySelector('.custom-select-trigger span')?.textContent === "日本語" && !dialog.querySelector('.custom-select-trigger').disabled, "language saved");
  const trigger = dialog.querySelector('.custom-select-trigger');
  trigger.click();
  await waitFor(() => document.querySelector('.custom-select-menu [aria-selected="true"]') === document.activeElement, "selected option focus");
  document.activeElement.dispatchEvent(new KeyboardEvent("keydown", { key: "Home", bubbles: true }));
  if (document.activeElement.dataset.value !== "system") throw new Error("Home did not focus first option");
  document.activeElement.dispatchEvent(new KeyboardEvent("keydown", { key: "e", bubbles: true }));
  if (document.activeElement.dataset.value !== "en") throw new Error("Typeahead did not find English");
  document.activeElement.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true }));
  await waitFor(() => !document.querySelector('.custom-select-menu'), "escape dismisses popup");
  report.selectModal = dialog.matches(":modal") && document.activeElement === trigger;
  trigger.click();
  await waitFor(() => document.querySelector('.custom-select-menu [data-value="en"]'), "restore English option");
  document.querySelector('.custom-select-menu [data-value="en"]').click();
  await waitFor(() => dialog.querySelector('.custom-select-trigger span')?.textContent === "English" && !dialog.querySelector('.custom-select-trigger').disabled, "English restored");
  dialog.querySelector('.dialog-heading button').click();

  const frame = document.createElement("iframe");
  frame.src = "/smoke/settings";
  frame.style.cssText = "position:fixed;inset:0;width:100%;height:100%;z-index:200;border:0";
  document.body.append(frame);
  try {
    await waitFor(() => frame.contentDocument?.querySelector('[data-page="Appearance"] .custom-select-trigger'), "settings UI fixture");
    const doc = frame.contentDocument;
    await select(doc, "Language", "en");
    await waitFor(() => frame.contentWindow.smokeSettings.snapshot.preferences.language === "en" && !doc.querySelector('.settings-content').disabled, "settings language saved");
    report.selectSettingsLanguage = !doc.querySelector("select");

    doc.querySelector('[data-section="Projects"]').click();
    await waitFor(() => !doc.querySelector('.settings-content').disabled, "projects ready");
    doc.querySelector('[data-page="Projects"] [data-entity-id="select-fixture"]').click();
    await waitFor(() => doc.querySelector('[aria-label="Automation model"]'), "automation editor");
    await select(doc, "Automation model", "codex-fixed");
    const effort = () => doc.querySelector('[aria-label="Automation reasoning level"]');
    await waitFor(() => effort().textContent === "Default", "incompatible effort reset");
    effort().click();
    await waitFor(() => doc.querySelector('.custom-select-menu'), "fixed reasoning menu");
    report.selectModelEffort = doc.querySelectorAll('.custom-select-menu [role="option"]').length === 1;
    doc.querySelector('.custom-select-menu [role="option"]').click();
    await select(doc, "Automation model", "");
    await select(doc, "Automation reasoning level", "high");
    await select(doc, "Automation agent", "claude");
    await waitFor(() => effort().textContent === "Default" && doc.querySelector('[aria-label="Automation model"]').textContent === "Default", "agent resets choices");
    const modelTrigger = doc.querySelector('[aria-label="Automation model"]');
    modelTrigger.click();
    await waitFor(() => doc.querySelector('.custom-select-menu'), "Claude models");
    report.selectAgentScoped = ![...doc.querySelectorAll('.custom-select-menu [role="option"]')].some((option) => option.dataset.value.startsWith("codex"));
    doc.querySelector('.custom-select-menu [data-value="claude-a"]').click();
    await select(doc, "Automation reasoning level", "max");
    await select(doc, "Automation permissions", "plan");
    const submit = doc.querySelector('[data-page="Projects"] button[type="submit"]');
    submit.click();
    await waitFor(() => frame.contentWindow.smokeSettings.commands.some((command) => command.kind === "save-project"), "automation saved");
    const saved = frame.contentWindow.smokeSettings.commands.findLast((command) => command.kind === "save-project").project.issues;
    report.selectAutomationSaved = saved.backend === "claude" && saved.model === "claude-a" && saved.effort === "max" && saved.permission === "plan";

    await waitFor(() => !doc.querySelector('[data-page="Projects"] fieldset').disabled, "save complete");
    modelTrigger.scrollIntoView({ block: "center", behavior: "instant" });
    await pause(60);
    modelTrigger.click();
    await waitFor(() => doc.querySelector('.custom-select-menu'), "disabled fieldset menu");
    doc.querySelector('.settings-content').disabled = true;
    await waitFor(() => !doc.querySelector('.custom-select-menu'), "fieldset disables open menu");
    report.selectDisabled = modelTrigger.matches(":disabled");
    doc.querySelector('.settings-content').disabled = false;

    doc.querySelector('[data-section="Service"]').click();
    await waitFor(() => doc.querySelector('[aria-label="Enable embedded Tailscale"]'), "tailnet service controls");
    const fixture = frame.contentWindow.smokeSettings;
    const button = (label) => [...doc.querySelectorAll('button')].find((item) => item.textContent.trim() === label);
    const idle = () => !doc.querySelector('.settings-content').disabled && !doc.querySelector('[data-page="Service"] fieldset').disabled;
    doc.querySelector('[aria-label="Enable embedded Tailscale"]').click();
    await waitFor(() => fixture.snapshot.settings.tsnet_enabled && doc.querySelector('[data-restart-service]') && idle(), "tailnet enable saved");
    const publicOriginInput = doc.querySelector('[aria-label^="Public origin"]');
    report.tailnetExplicitRestart = !fixture.commands.some((command) => command.kind === "restart-service") && !publicOriginInput.disabled;
    doc.querySelector('[data-restart-service]').click();
    await waitFor(() => button("Sign in to Tailscale") && idle(), "browser enrollment option");
    report.tailnetMissingLoginLink = fixture.snapshot.status.TSNet.AuthURL === "" && !button("Sign in to Tailscale").disabled;
    fixture.failNextLogin = true;
    fixture.holdNextLogin = true;
    button("Sign in to Tailscale").click();
    await waitFor(() => button("Getting login link...")?.disabled, "login request feedback");
    if (!idle() || button("Stop service").disabled) throw new Error("Login request blocks service controls");
    doc.querySelector('[data-section="Network"]').click();
    await waitFor(() => !doc.querySelector('[data-page="Network"]').hidden && idle(), "navigate during login request");
    const enableProxy = () => doc.querySelector('[aria-label="Enable proxy"]');
    const proxy = () => doc.querySelector('[aria-label="Use system proxy"]');
    const proxyURL = () => doc.querySelector('[aria-label="Proxy URL"]');
    const noProxy = () => doc.querySelector('[aria-label="No proxy"]');
    const editNetworkField = (input, value) => {
      input.focus();
      Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLInputElement.prototype, "value").set.call(input, value);
      input.dispatchEvent(new frame.contentWindow.Event("input", { bubbles: true }));
      input.blur();
    };
    editNetworkField(proxyURL(), "http://127.0.0.1:8889");
    await waitFor(() => fixture.snapshot.settings.proxy_url === "http://127.0.0.1:8889", "custom proxy saved on blur");
    editNetworkField(noProxy(), "localhost,127.0.0.1,internal.example");
    await waitFor(() => fixture.snapshot.settings.no_proxy === "localhost,127.0.0.1,internal.example", "proxy bypass saved on blur");
    proxy().click();
    await waitFor(() => fixture.snapshot.settings.use_system_proxy && proxy().getAttribute("aria-checked") === "true" && !proxy().disabled && proxyURL().disabled && noProxy().disabled, "system mode disables custom inputs");
    enableProxy().click();
    await waitFor(() => !fixture.snapshot.settings.proxy_enabled && proxy().disabled && proxyURL().disabled && noProxy().disabled, "master switch disables all proxy controls");
    if (!fixture.snapshot.settings.use_system_proxy || fixture.snapshot.settings.proxy_url !== "http://127.0.0.1:8889" || fixture.snapshot.settings.no_proxy !== "localhost,127.0.0.1,internal.example") throw new Error("Disabling proxies discarded saved mode or custom values");
    enableProxy().click();
    await waitFor(() => fixture.snapshot.settings.proxy_enabled && !proxy().disabled && proxyURL().disabled, "master switch restores system mode");
    proxy().click();
    await waitFor(() => !fixture.snapshot.settings.use_system_proxy && !proxyURL().disabled && !noProxy().disabled, "custom proxy enabled again");
    report.networkProxySettings = !doc.querySelector('[data-page="Service"] [aria-label="Use system proxy"]') && fixture.snapshot.settings.tsnet_enabled && fixture.snapshot.settings.host === "127.0.0.1" && proxyURL().value === "http://127.0.0.1:8889" && noProxy().value === "localhost,127.0.0.1,internal.example";
    report.tailnetLoginNonBlocking = Boolean(button("Getting login link...")) && idle();
    doc.querySelector('[data-section="Service"]').click();
    await waitFor(() => !doc.querySelector('[data-page="Service"]').hidden && idle(), "return to pending login");
    fixture.releaseLogin();
    await waitFor(() => doc.querySelector('[role="alert"]')?.textContent.includes("Check network access") && button("Sign in to Tailscale") && idle(), "login network error and retry");
    report.tailnetLoginFeedback = !button("Sign in to Tailscale").disabled;
    button("Sign in to Tailscale").click();
    await waitFor(() => fixture.snapshot.status.TSNet.AuthURL && idle(), "browser login command");
    report.tailnetBrowserLogin = fixture.snapshot.status.TSNet.State === "NeedsLogin" && fixture.commands.filter((command) => command.kind === "tsnet-login").length === 2;

    const key = doc.querySelector('[aria-label="Tailscale Auth Key (optional)"]');
    Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLInputElement.prototype, "value").set.call(key, "tskey-auth-test-only-not-a-real-key");
    key.dispatchEvent(new frame.contentWindow.Event("input", { bubbles: true }));
    await waitFor(() => !button("Use Auth Key").disabled, "key input ready");
    fixture.failNextRegistration = true;
    button("Use Auth Key").click();
    await waitFor(() => doc.querySelector('[role="alert"]')?.textContent.includes("Auth Key rejected") && !button("Use Auth Key").disabled, "key rejection is actionable");
    if (!key.value) throw new Error("Failed registration discarded the retryable key");
    fixture.holdNextRegistration = true;
    const restarts = fixture.commands.filter((command) => command.kind === "restart-service").length;
    button("Use Auth Key").click();
    await waitFor(() => button("Registering with Auth Key...")?.disabled, "immediate key registration feedback");
    report.tailnetKeyNonBlocking = idle() && !button("Stop service").disabled && !doc.querySelector('[data-section="Network"]').disabled;
    fixture.releaseRegistration();
    await waitFor(() => fixture.snapshot.status.TSNet.State === "Registered" && key.value === "" && button("Use Auth Key").disabled && idle(), "key registered without restart");
    report.tailnetKeyRegistration = fixture.commands.filter((command) => command.kind === "restart-service").length === restarts && fixture.snapshot.status.Running && fixture.snapshot.status.TSNet.URL === "";
    report.tailnetSecretInput = key.type === "password" && !JSON.stringify(fixture.snapshot).includes("tskey-auth-") && !button("Clear pending key");
    await waitFor(() => doc.querySelector('[data-restart-service]') && idle(), "registered node restart action");
    doc.querySelector('[data-restart-service]').click();
    await waitFor(() => doc.querySelector('code')?.textContent === "https://spool.example.ts.net" && idle(), "assigned HTTPS origin");
    report.tailnetConnected = !fixture.snapshot.status.TSNetAuthKeySet && !button("Clear pending key") && !button("Sign in to Tailscale") && !doc.querySelector('[data-restart-service]') && fixture.snapshot.settings.public_url === "https://chat.example.com" && publicOriginInput.value === "https://chat.example.com" && !publicOriginInput.disabled;
    const nextPublicOrigin = "https://pwa.example.com";
    Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLInputElement.prototype, "value").set.call(publicOriginInput, nextPublicOrigin);
    publicOriginInput.dispatchEvent(new frame.contentWindow.Event("input", { bubbles: true }));
    publicOriginInput.focus();
    publicOriginInput.blur();
    await waitFor(() => fixture.snapshot.settings.public_url === nextPublicOrigin && doc.querySelector('[data-restart-service]') && fixture.snapshot.status.TSNet.URL === "https://spool.example.ts.net", "public origin saved independently");
    doc.querySelector('[data-restart-service]').click();
    await waitFor(() => !doc.querySelector('[data-restart-service]') && fixture.snapshot.settings.public_url === nextPublicOrigin && fixture.snapshot.status.TSNet.URL === "https://spool.example.ts.net" && idle(), "restart retains both origins");
    report.tailnetPublicOriginIndependent = publicOriginInput.value === nextPublicOrigin && !publicOriginInput.disabled && fixture.snapshot.status.TSNet.URL === "https://spool.example.ts.net";
    const assertSettingsViewport = () => {
      const view = frame.contentWindow;
      const root = doc.scrollingElement;
      const shell = doc.querySelector('.desktop-settings-shell').getBoundingClientRect();
      const main = doc.querySelector('.settings-main');
      const mainBounds = main.getBoundingClientRect();
      const footer = doc.querySelector('.settings-sidebar-bottom').getBoundingClientRect();
      if (root.scrollHeight > view.innerHeight || root.scrollWidth > view.innerWidth || root.scrollTop || shell.top !== 0 || Math.abs(footer.bottom - view.innerHeight) > 1)
        throw new Error("Settings escaped its content scroller: " + JSON.stringify({ height: view.innerHeight, scrollHeight: root.scrollHeight, scrollTop: root.scrollTop, shellTop: shell.top, shellHeight: shell.height, mainTop: mainBounds.top, mainBottom: mainBounds.bottom, mainHeight: mainBounds.height, mainScrollHeight: main.scrollHeight, footerBottom: footer.bottom }));
    };
    assertSettingsViewport();
    const copy = doc.querySelector('.settings-copy-address');
    copy.scrollIntoView({ block: "center", behavior: "instant" });
    copy.focus({ preventScroll: true });
    await pause(180);
    frame.contentWindow.scrollTo(0, 100000);
    assertSettingsViewport();
    const main = doc.querySelector('.settings-main');
    const service = doc.querySelector('[data-page="Service"]');
    const shape = () => {
      const rect = copy.getBoundingClientRect();
      return [rect.x, rect.y, rect.width, rect.height, main.scrollTop, main.scrollWidth, main.clientWidth, service.getBoundingClientRect().height];
    };
    const beforeCopy = shape();
    const executions = fixture.executes;
    const mutations = [];
    const observer = new frame.contentWindow.MutationObserver((records) => mutations.push(...records));
    observer.observe(doc.querySelector('.desktop-settings-shell'), { subtree: true, childList: true, attributes: true, characterData: true });
    fixture.holdNextCopy = true;
    copy.click();
    await waitFor(() => copy.getAttribute("aria-busy") === "true" && fixture.releaseCopy, "local clipboard wait state");
    if (!idle() || button("Stop service").disabled || doc.querySelector('[data-section="Network"]').disabled || doc.activeElement !== copy) throw new Error("Clipboard wait blocked controls or lost focus");
    fixture.releaseCopy();
    await waitFor(() => copy.querySelector('[role="status"]').textContent === "Copied", "local copy acknowledgement");
    if (shape().some((value, index) => Math.abs(value - beforeCopy[index]) > 0.5)) throw new Error("Copy acknowledgement shifted settings layout");
    fixture.failNextCopy = true;
    copy.click();
    await waitFor(() => copy.querySelector('[role="status"]').textContent.includes("Could not copy"), "copy failure is retryable");
    copy.click();
    await waitFor(() => copy.querySelector('[role="status"]').textContent === "Copied", "copy failure retry succeeds");
    await waitFor(() => copy.getAttribute("title") === "Copy address", "copy acknowledgement cleared");
    observer.disconnect();
    report.settingsCopyStable = shape().every((value, index) => Math.abs(value - beforeCopy[index]) <= 0.5) && fixture.executes === executions && doc.activeElement === copy && mutations.every((record) => copy.contains(record.target));
    if (!report.settingsCopyStable) throw new Error("Copy mutated unrelated settings or lost scroll/focus");
    assertSettingsViewport();

    // A complete unchanged bridge poll must not even mutate the visible DOM.
    await pause(100);
    const pollMutations = [];
    const pollObserver = new frame.contentWindow.MutationObserver((records) => pollMutations.push(...records));
    pollObserver.observe(doc.querySelector('.settings-content'), { subtree: true, attributes: true, childList: true, characterData: true });
    const pollCount = fixture.snapshots;
    await waitFor(() => fixture.snapshots > pollCount, "unchanged settings poll");
    await pause(80);
    pollObserver.disconnect();
    report.settingsPollingStable = pollMutations.length === 0 && doc.activeElement === copy && shape().every((value, index) => Math.abs(value - beforeCopy[index]) <= 0.5);
    if (!report.settingsPollingStable) throw new Error("Unchanged poll mutated settings DOM or lost focus");

    const projectInput = doc.querySelector('[data-page="Projects"] [aria-label="Project name"]');
    const projectDraft = projectInput.value;
    doc.querySelector('[data-section="Network"]').click();
    await waitFor(() => !doc.querySelector('[data-page="Network"]').hidden, "network after copy");
    doc.querySelector('[data-section="Projects"]').click();
    await waitFor(() => !doc.querySelector('[data-page="Projects"]').hidden, "project editor restored");
    report.settingsDraftRetained = projectInput === doc.querySelector('[data-page="Projects"] [aria-label="Project name"]') && projectInput.value === projectDraft;
    report.tailnetCopyURL = true;
  } finally {
    frame.remove();
  }
}
